(1903119, 262726, 41675, '<td valign="top">Without the benefit of your title, I''m not sure how well this could fit into this challenge. I do like the off-centered composition.</td>', 'Without the benefit of your title, I''m not sure how well this could fit into this challenge. I do like the off-centered composition.', '2005-11-28 19:25:02.000000', NULL, 1),
(1903121, 261234, 41675, '<td valign="top">Your photo seems a bit on the blue side of the spectrum (although you may have done that intentionally?) Seems a bit of a stretch to fit the challenge, but that''s just me.</td>', 'Your photo seems a bit on the blue side of the spectrum (although you may have done that intentionally?) Seems a bit of a stretch to fit the challenge, but that''s just me.', '2005-11-28 19:26:45.000000', NULL, 1),
(1903122, 262395, 42492, '<td valign="top">nice and cute at the same time. very good</td>', 'nice and cute at the same time. very good', '2005-11-28 19:26:48.000000', NULL, 1),
(1903125, 262594, 41675, '<td valign="top">I wish there was a bit more focus. It reminds me of a holiday lawn ornament rather than a hot rod. I wonder if a bit more definition around the blackened areas of the car would help?</td>', 'I wish there was a bit more focus. It reminds me of a holiday lawn ornament rather than a hot rod. I wonder if a bit more definition around the blackened areas of the car would help?', '2005-11-28 19:28:03.000000', NULL, 1),
(1903126, 262636, 42492, '<td valign="top">good one. nice challenge photo</td>', 'good one. nice challenge photo', '2005-11-28 19:29:12.000000', NULL, 1),
(1903127, 261383, 41675, '<td valign="top">For me personally, your photo gives a sense of abandonment, lost and lonely. I like the use of black and white.</td>', 'For me personally, your photo gives a sense of abandonment, lost and lonely. I like the use of black and white.', '2005-11-28 19:29:17.000000', NULL, 1),
(1903130, 261175, 41675, '<td valign="top">If you had pulled back a bit and maybe shown more of the glass or liquid - to help represent adulthood - I would have score it better. This is would make an interesting background pattern.</td>', 'If you had pulled back a bit and maybe shown more of the glass or liquid - to help represent adulthood - I would have score it better. This is would make an interesting background pattern.', '2005-11-28 19:30:16.000000', NULL, 1),
