(1903134, 261274, 41675, '<td valign="top">I like the shadow of the dog, but from your title I get the sense that kids aren''t allowed to have dogs? I think I''m missing the point you were trying to get across. Sorry.</td>', 'I like the shadow of the dog, but from your title I get the sense that kids aren''t allowed to have dogs? I think I''m missing the point you were trying to get across. Sorry.', '2005-11-28 19:31:15.000000', NULL, 1),
(1903135, 262113, 41675, '<td valign="top">For me, this would make a very interesting pattern background, but seems a bit of a stretch to have such a tight closeup. Perhaps if there were more of the garment showing or another object or two in the shot also, it would enhance your message.</td>', 'For me, this would make a very interesting pattern background, but seems a bit of a stretch to have such a tight closeup. Perhaps if there were more of the garment showing or another object or two in the shot also, it would enhance your message.', '2005-11-28 19:32:15.000000', NULL, 1),
(1903137, 261981, 41675, '<td valign="top">While I like the off centered composition and the blurred background, I''m personally having a hard time relating your photo to the challenge. (Which means it will probably score well) ha ha.</td>', 'While I like the off centered composition and the blurred background, I''m personally having a hard time relating your photo to the challenge. (Which means it will probably score well) ha ha.', '2005-11-28 19:33:15.000000', NULL, 1),
