(1903857, 262661, 39349, '<td valign="top">Great idea, but seems a bit dark on my end. The whole picture that is. Maybe bumping up the brightness / contrast would give this image more impact? 5 from me.</td>', 'Great idea, but seems a bit dark on my end. The whole picture that is. Maybe bumping up the brightness / contrast would give this image more impact? 5 from me.', '2005-11-29 02:04:16.000000', NULL, 1),
(1903858, 261972, 39349, '<td valign="top">WOW this is a surprise. Great colors, I like how you''ve captured such a bright subject without blowing out your whites. 8 from me.</td>', 'WOW this is a surprise. Great colors, I like how you''ve captured such a bright subject without blowing out your whites. 8 from me.', '2005-11-29 02:05:21.000000', NULL, 1),
(1903859, 262560, 39349, '<td valign="top">Beautiful study in b/w, tonal range is perfect IMHO. Interesting shot that draws the viewer in for closer examination.</td>', 'Beautiful study in b/w, tonal range is perfect IMHO. Interesting shot that draws the viewer in for closer examination.', '2005-11-29 02:06:28.000000', NULL, 1),
