(1912798, 262656, 48904, '<td valign="top">This is Great !!!! Captured a Lovely Moment !!!!</td>', 'This is Great !!!! Captured a Lovely Moment !!!!', '2005-12-01 13:46:04.000000', NULL, 1),
(1912802, 262724, 48904, '<td valign="top">Wonderful Shot !!!!</td>', 'Wonderful Shot !!!!', '2005-12-01 13:46:52.000000', NULL, 1),
(1912808, 262780, 22734, '<td valign="top">A very nice concept of juggling lif''e affairs. Now, while the idea is great the execution just lacks the final touch with the lighting and focus. However, do not be too discouraged as lighting and focus can be easily learned but  the creative mind is either present or not. You are creative and you have a nice eye. When doing these images the secret is to take the shot as you desire and then go into lighting and focus variations as well as different angles. Now you wind up with maybe 15 or 25 takes. Bumping up on great concept.</td>', 'A very nice concept of juggling lif''e affairs. Now, while the idea is great the execution just lacks the final touch with the lighting and focus. However, do not be too discouraged as lighting and focus can be easily learned but  the creative mind is either present or not. You are creative and you have a nice eye. When doing these images the secret is to take the shot as you desire and then go into lighting and focus variations as well as different angles. Now you wind up with maybe 15 or 25 takes. Bumping up on great concept.', '2005-12-01 13:47:39.000000', NULL, 1),
(1913266, 262026, 15002, '<td valign="top">The image is very noisy and the DOF is too shallow IMO.  Does not seem to meet the challenge if the "Eye" is an adult.</td>', 'The image is very noisy and the DOF is too shallow IMO.  Does not seem to meet the challenge if the "Eye" is an adult.', '2005-12-01 15:31:21.000000', NULL, 1),
