INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1924101, 262613, 2022, '<td valign="top">Great work, congratulations on your ribbon !</td>', 'Great work, congratulations on your ribbon !', '2005-12-05 13:40:52.000000', NULL, 0),
(1924108, 262704, 2022, '<td valign="top">Congratulations !</td>', 'Congratulations !', '2005-12-05 13:41:57.000000', NULL, 0),
