(1924145, 262787, 40370, '<td valign="top">Top twenty rocks, way to unlock the DPC magic again Steve, congrats !</td>', 'Top twenty rocks, way to unlock the DPC magic again Steve, congrats !', '2005-12-05 13:56:31.000000', NULL, 0),
(1924207, 262065, 29904, '<td valign="top">This is a really great idea and nicely shot!  As others said, white balance off, and busy which makes it hard to figure out.  But great composition, DOF, and angle!  (this needs to trade places with the 15th place holder IMO ;)</td>', 'This is a really great idea and nicely shot!  As others said, white balance off, and busy which makes it hard to figure out.  But great composition, DOF, and angle!  (this needs to trade places with the 15th place holder IMO ;)', '2005-12-05 14:09:47.000000', NULL, 0),
(1924211, 261243, 22734, '<td valign="top">Congratulations on your top 20 finish with this neatly presented collection. Very well done.</td>', 'Congratulations on your top 20 finish with this neatly presented collection. Very well done.', '2005-12-05 14:11:01.000000', NULL, 0),
(1924232, 261383, 22734, '<td valign="top">It is amazing how we readily project our feelings and emotions to inanimate objects. Consider the strong attachments that children place on them and then even as we grow up we still feel an affinity. Well, when seen, as this abondoned, it touches something deep within us. Hence the strength of this image. Here you have conveyed and awaken these feelings. Congratulations on your top 20 finish.</td>', 'It is amazing how we readily project our feelings and emotions to inanimate objects. Consider the strong attachments that children place on them and then even as we grow up we still feel an affinity. Well, when seen, as this abondoned, it touches something deep within us. Hence the strength of this image. Here you have conveyed and awaken these feelings. Congratulations on your top 20 finish.', '2005-12-05 14:17:46.000000', NULL, 0),
(1924234, 262515, 22734, '<td valign="top">Congratulations on your top 20 finish with this denim texture beauty.</td>', 'Congratulations on your top 20 finish with this denim texture beauty.', '2005-12-05 14:18:25.000000', NULL, 0),
(1924237, 262560, 22734, '<td valign="top">A peek into the world of the adult and the sum of his love and aspirations. The sepia here adds that added touch. Congratulations on your top 20 finish</td>', 'A peek into the world of the adult and the sum of his love and aspirations. The sepia here adds that added touch. Congratulations on your top 20 finish', '2005-12-05 14:19:46.000000', NULL, 0),
